observations:

alcohol use = nearly everyone, meaningful spread across risk levels too
other substance use is less prevalenct, but does seem to be more moderate risk (though the low-risk threshold is pretty low, so even occasional use is likely to be moderate??)
high risk drug use = uncommon, but evident
cannabis, amphetamines, and sedatives more skewed to moderate, rather than low risk







Notemodelling decision



rather than modelling each drug individually, use max other drug score as indicator.



Summary based on alcohol risk:

restrict to recent alcohol users (past 3 months)
stratify by ASSIST risk
compare continuous with kruskal-wallis and gender with chi-squared



Code
# Summary based on alcohol risk scores
tbl_alc &lt;- df |&gt;
  filter(recent_alcohol_user == 1) |&gt;
  dplyr::select(
    gender,
    age,
    agency_years,
    alcohol_use_interpretation,
    k10_total,
    absenteeism = k10_11_absenteeism,
    presenteeism = k10_12_presenteeism
  ) |&gt;
  tbl_summary(
    by = alcohol_use_interpretation,
    missing = "no",
    missing_text = "Missing",
    statistic = list(
      all_continuous() ~ c("{mean} ({sd})"),
      all_categorical() ~ "{n} ({p}%)"
    ),
    percent = "row",
    digits = list(all_continuous() ~ c(1, 1), all_categorical() ~ c(0, 1)),
    label = list(
      gender = "Gender",
      age = "Age",
      k10_total = "Psychological distress",
      absenteeism = "Absenteeism",
      presenteeism = "Presenteeism",
      agency_years = "Agency years",
      alcohol_use_interpretation = "Alcohol use risk category"
    )
  ) |&gt;
  add_n(statistic = "{N_nonmiss}", col_label = "n") |&gt;
  modify_header(list(
    label ~ "Characteristic",
    stat_1 ~ "Low Risk\n(n = 77)",
    stat_2 ~ "Moderate Risk\n(n = 83)",
    stat_3 ~ "High Risk\n(n = 56)"
  )) |&gt;
  add_p(
    test = list(all_continuous() ~ "kruskal.test", gender ~ "chisq.test"),

    #test.args = all_categorical() ~ list(simulate.p.value = TRUE),
    pvalue_fun = function(x) {
      formatted &lt;- ifelse(x &lt; 0.001, "&lt;.001", sprintf("%.3f", x))
      sub("^0\\.", ".", formatted)
    }
  ) |&gt;
  add_stat_label(
    label = list(all_continuous() ~ "Mean (SD)", all_categorical() ~ "n (%)")
  ) |&gt;
  modify_footnote(everything() ~ NA) |&gt;
  modify_header(p.value ~ "p") |&gt;
  gtsummary::as_flex_table() |&gt; 
  my_flextable()
